window.POETRY_REGISTER("v5-strict-12-11-0-7bd5067edea0.js",{"poems":[[3053,2],[47464,2],[48783,2],[49683,2],[55803,2],[55834,2],[134246,7],[136230,7],[140225,7],[150068,7],[266880,7],[289440,7],[368169,10],[472650,8],[474408,8],[509931,8],[650074,5],[672350,5],[725087,5]],"pairs":[["既不能断绝蒺藜荆棘之根株","又不能展凤皇麒麟之拳跼",0],["君不见金陵风台月榭烟霞光","如今五里十里野火烧茫茫",1],["既不能断绝蒺藜荆棘之根株","又不能展凤皇麒麟之拳跼",2],["是知贪名徇禄而随世磨灭者","虽正寝之死乎无得与吾俦",3],["今检同书有小天赵为山云云","知此诗为赵崇赠崔胤之作",4],["二问政山在歙州城外十许里","其地唐末适为钟传所奄有",5],["山谷老人所以强名之而无媿","姑溪居士又从而雪上加霜",6],["人闻拏音兮不知何处散发醉","高荷为盖兮倚芙蓉以当伎",7],["欲泉利之专兮先耘耨之不偷","无忘吾语兮若吾岁之来游",8],["吾既不能为乔松直干摩苍天","又不能为小童一线飞纸鸢",9],["升坎降离凝正一而融三五兮","付之灵坚童子玉池太和官",10],["余经山之外兮覩山水之杳冥","佳气葱鬰兮或天香而龙腥",11],["秦关桃林之寒赑屃于其左兮","右抱万顷白玉所产之蓝田",12],["君不见长江滔滔发源来自西","坎德至清且洁彻底无浊泥",13],["君不见昆仑高高阆风出其上","下视扶桑弱水相去几千丈",14],["士有白袍倡文运而肇破天荒","有黄榜推少年而歆羡时辈",15],["给了他个泰山压顶没有躲闪","直杀的血流漂杵堵了城门",16],["姑夫的家业又落在他妻侄手","柴世宗贩伞的螟蛉倒不差",16],["公等诚不能案摩析枝为长者","吾能挟山超海独障狂澜东",17],["吁嗟乎蜀道险巇不可以径度","何不掷杖成桥引入大罗天",18]]});
